), ins as (
insert into programs (school_id,name,level,field,mode,duration_years,entry_note,verified,demo)
select s.id,v.name,v.lvl,'Education',v.mode,v.yrs,
 'UNVERIFIED. Listed for this college by ChatGPT from public college, university and Ghana Tertiary Education Commission pages (researched 23 October 2026). Awarded through '||v.uni||'. '||
 case v.flag
  when 's' then 'Entry for school leavers (2026/2027 shared admission requirements for colleges of education, https://admission.coeportal.edu.gh/ADMISSION_REQUIREMENTS_2026.pdf): WASSCE six credits A1 to C6 including English, Core Mathematics, Integrated Science or Social Studies, and three relevant electives. '
  when 'o' then 'Programme taken from an older shared list (2022/2023), so check it is still offered. Entry for school leavers: WASSCE six credits A1 to C6, three core and three relevant electives. '
  when 'm' then 'Entry for school leavers (college page): WASSCE six credits A1 to C6 including English, Mathematics and three subjects relevant to the specialisation. '
  when 'w' then 'Entry for school leavers: WASSCE six credit passes in three core and three relevant electives. The college quoted a provisional total of GHS 5,378.80 for 2026/2027 (academic and related fees, accommodation and SRC levy extra), which is not shown as the annual fee because a subsidy balance was also stated. '
  when 'b' then 'The college page names UCC but a T-TEL list names UEW, so the affiliation is not confirmed. Entry for school leavers: WASSCE six credits A1 to C6 including English, Core Mathematics, Integrated Science or Social Studies, and three relevant electives. '
  when 'c' then 'Entry for school leavers (college page): six subjects including English, Mathematics, Science or Social Studies and electives, aggregate 42 or better, plus an interview. '
  when 't' then 'Top-up route described by the college for diploma holders (DBE and similar), by sandwich in two sessions. '
  else 'Entry rule not published for this listing and current intake not confirmed. ' end
 ||'Fees are not published. Apply through the Colleges of Education admission portal (https://admission.coeportal.edu.gh).',
 false,false
from v join schools s on s.name=v.sch
where not exists (select 1 from programs p where p.school_id=s.id and lower(p.name)=lower(v.name))
returning school_id)
select (select count(*) from ins) inserted, (select count(distinct sch) from v) colleges_in_data, (select count(*) from v) rows_in_data, (select count(*) from v where sch not in (select name from schools)) unmatched;
